import { Form } from './base/Form';
export class Order extends Form {
    constructor(container, events) {
        super(container, events);
        this._buttonCard = this.container.elements.namedItem('card');
        this._buttonCash = this.container.elements.namedItem('cash');
        this._buttonCard.addEventListener('click', () => {
            this._buttonCard.classList.add('button_alt-active');
            this._buttonCash.classList.remove('button_alt-active');
            this.onInputChange('payment', this._buttonCard.name);
        });
        this._buttonCash.addEventListener('click', () => {
            this._buttonCash.classList.add('button_alt-active');
            this._buttonCard.classList.remove('button_alt-active');
            this.onInputChange('payment', this._buttonCash.name);
        });
    }
    set address(value) {
        this.container.elements.namedItem('address').value = value;
    }
    set payment(value) {
        if (value) {
            this.toggleClass(this.container.elements.namedItem(value), 'button_alt-active', true);
        }
        else {
            this._buttonCard.classList.remove('button_alt-active');
            this._buttonCash.classList.remove('button_alt-active');
        }
    }
}
