import { Api } from './base/api';
import { replaceSvgWithPng } from '../../utils/utils';
export class WebLarekAPI extends Api {
    constructor(cdn, baseUrl, options) {
        super(baseUrl, options);
        this.cdn = cdn;
    }
    getProducts() {
        return this.get('/product').then((data) => data.items.map((item) => (Object.assign(Object.assign({}, item), { image: replaceSvgWithPng(this.cdn + item.image) }))));
    }
    sendOrder(data) {
        return this.post('/order', data).then((data) => data);
    }
}
